# CLASSE: CacheManager (MELHORADA)
# ────────────────────────────────────────────────────────────────────────────────
class CacheManager:
    def __init__(self, default_ttl=300, max_size=100):
        self._cache = OrderedDict()
        self._default_ttl = default_ttl
        self._max_size = max_size
        self._lock = asyncio.Lock()
        self._hits = 0
        self._misses = 0

    async def get(self, key):
        async with self._lock:
            if key in self._cache:
                value = self._cache[key]
                if time_module.time() - value['timestamp'] < value.get('ttl', self._default_ttl):
                    self._cache.move_to_end(key)
                    self._hits += 1
                    return value.get('data')
                else:
                    del self._cache[key]
            self._misses += 1
            return None

    async def set(self, key, data, ttl=None):
        async with self._lock:
            if len(self._cache) >= self._max_size:
                oldest = next(iter(self._cache))
                del self._cache[oldest]
            self._cache[key] = {
                'data': data,
                'ttl': ttl or self._default_ttl,
                'timestamp': time_module.time()
            }
            self._cache.move_to_end(key)

    async def delete(self, key):
        async with self._lock:
            if key in self._cache:
                del self._cache[key]

    async def clear(self):
        async with self._lock:
            self._cache.clear()

    async def clean_expired(self):
        async with self._lock:
            now = time_module.time()
            expired = []
            for key, value in self._cache.items():
                if now - value['timestamp'] > value.get('ttl', self._default_ttl):
                    expired.append(key)
            for key in expired:
                del self._cache[key]
            return len(expired)

    def size(self):
        return len(self._cache)

    def stats(self):
        total = self._hits + self._misses
        hit_rate = (self._hits / total * 100) if total > 0 else 0
        return {
            "size": self.size(),
            "hits": self._hits,
            "misses": self._misses,
            "hit_rate": f"{hit_rate:.1f}%"
        }

# ────────────────────────────────────────────────────────────────────────────────
# INSTÂNCIA: cache
# ────────────────────────────────────────────────────────────────────────────────
cache = CacheManager(default_ttl=300, max_size=100)

