# FUNÇÃO: embed_padrao
# ────────────────────────────────────────────────────────────────────────────────
def embed_padrao(
    titulo: str,
    descricao: str = "",
    cor: int = None,
    emoji: str = None,
    autor: str = None,
    thumbnail_bot: bool = True,
    footer: str = None,
    timestamp: bool = True
) -> discord.Embed:
    if emoji:
        titulo = f"{emoji} {titulo}"

    embed = discord.Embed(
        title=titulo,
        description=descricao,
        color=cor or CoresUX.PRIMARIA,
        timestamp=agora() if timestamp else None
    )

    if autor:
        embed.set_author(
            name=f"🛡 Vida Rasa 442 • {autor}",
            icon_url=bot.user.display_avatar.url if bot.user else None
        )
    elif thumbnail_bot:
        embed.set_author(
            name="🛡 Vida Rasa 442",
            icon_url=bot.user.display_avatar.url if bot.user else None
        )

    if thumbnail_bot and bot.user:
        embed.set_thumbnail(url=bot.user.display_avatar.url)

    if footer:
        embed.set_footer(
            text=f"🛡 Vida Rasa 442 • {footer}",
            icon_url=bot.user.display_avatar.url if bot.user else None
        )
    elif timestamp:
        embed.set_footer(
            text=f"🛡 Vida Rasa 442 • {agora().strftime('%d/%m/%Y às %H:%M')}",
            icon_url=bot.user.display_avatar.url if bot.user else None
        )

    return embed

