# FUNÇÃO: enviar_painel_lives
# ────────────────────────────────────────────────────────────────────────────────
async def enviar_painel_lives():
    canal = bot.get_channel(CANAL_CADASTRO_LIVE_ID)
    if not canal: return

    embed = discord.Embed(
        title="🎥 ── CENTRAL DE LIVES ── 🎥",
        description="**VDR 442 • Divulgação de Streams**\n*Cadastre e anuncie suas lives para a facção*",
        color=0x9146FF,
        timestamp=agora()
    )
    embed.set_thumbnail(url=bot.user.display_avatar.url if bot.user else None)

    embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)

    embed.add_field(
        name="🟣 TWITCH (AUTOMÁTICO)",
        value="Cadastre sua live **uma única vez**. Quando você entrar ao vivo, o bot anuncia automaticamente no canal de divulgação.",
        inline=False
    )

    embed.add_field(
        name="🟢 KICK / 📱 TIKTOK / ▶️ YOUTUBE (MANUAL)",
        value="Toda vez que for começar a live, publique manualmente. Preencha os dados e o anúncio vai imediatamente para o canal.",
        inline=False
    )

    embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)
    embed.add_field(name="📢 DESTINO", value=f"Todas as lives vão para: <#{CANAL_DIVULGACAO_LIVE_ID}>", inline=False)

    embed.set_footer(text=f"🛡 Vida Rasa 442 • Sistema de Lives", icon_url=bot.user.display_avatar.url if bot.user else None)

    try:
        async for msg in canal.history(limit=30):
            if msg.author == bot.user:
                try: await msg.delete()
                except: pass
        await canal.send(embed=embed, view=PainelLivesUnicoView())
    except Exception as e:
        logger.error(f"❌ Erro ao enviar painel de lives: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# LOOP: verificar_lives
# ────────────────────────────────────────────────────────────────────────────────
@tasks.loop(minutes=2)
async def verificar_lives():
    try:
        lives = await carregar_lives_db()
        if not lives:
            return
        for row in lives:
            user_id = row["user_id"]
            link = row["link"]
            divulgado = row["divulgado"]
            if not link:
                continue
            plataforma = detectar_plataforma(link)
            canal_name = extrair_canal(link)
            if not plataforma or not canal_name:
                continue
            if plataforma != "twitch":
                continue
            ao_vivo = False
            titulo = None
            jogo = None
            thumbnail = None
            try:
                ao_vivo, titulo, jogo, thumbnail = await checar_twitch(canal_name)
            except Exception as e:
                logger.error(f"❌ Erro ao verificar Twitch/{canal_name}: {e}")
                continue
            if not ao_vivo and divulgado:
                await atualizar_divulgado_db(link, False)
            if ao_vivo and not divulgado:
                resultado = await divulgar_live(user_id, link, titulo, jogo, thumbnail)
                if resultado:
                    await atualizar_divulgado_db(link, True)
    except Exception as e:
        logger.error(f"❌ Erro no loop de lives: {e}")

