# ────────────────────────────────────────────────────────────────────────────────
# CLASSE: ResultadoGanhouModal (DIVISÃO COLETIVA DOS SOLDADOS)
# ────────────────────────────────────────────────────────────────────────────────
class ResultadoGanhouModal(discord.ui.Modal, title="🎉 Resultado - GANHOU"):
    dinheiro = discord.ui.TextInput(
        label="💰 Valor total ganho",
        placeholder="Ex: 50000",
        required=True
    )

    def __init__(self, acao_id, mensagem_original):
        super().__init__()
        self.acao_id = acao_id
        self.mensagem_original = mensagem_original

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)
        try:
            valor_total = safe_int(self.dinheiro.value)
            if valor_total <= 0:
                raise ValueError
        except:
            await interaction.followup.send("❌ Valor inválido!", ephemeral=True)
            return

        pool = await get_pool()
        if not pool:
            await interaction.followup.send("❌ Banco de dados indisponível!", ephemeral=True)
            return

        async with pool.acquire() as conn:
            acao = await conn.fetchrow("SELECT tipo FROM acoes_semana WHERE id=$1", self.acao_id)

            limite = ACOES_COMPLEXO.get(acao["tipo"]) or ACOES_BAHAMAS.get(acao["tipo"]) or ACOES_HELICRASH.get(acao["tipo"])
            if limite and limite is not None:
                qtd_feita = await conn.fetchval(
                    "SELECT COUNT(*) FROM acoes_semana WHERE tipo=$1 AND resultado='ganhou' AND id != $2",
                    acao["tipo"], self.acao_id
                )
                if qtd_feita >= limite:
                    await interaction.followup.send(
                        f"❌ Ação **{acao['tipo']}** já atingiu o limite semanal de **{limite}** vitória(s)!",
                        ephemeral=True
                    )
                    return

            await conn.execute(
                "UPDATE acoes_semana SET valor=$1, resultado='ganhou' WHERE id=$2",
                valor_total, self.acao_id
            )

            try:
                await movimentar_caixa(
                    tipo="acao",
                    valor=valor_total,
                    motivo=f"Ação ganha: {acao['tipo']} (ID {self.acao_id})",
                    autor=interaction.user.id,
                    tipo_dinheiro="sujo"
                )
                logger.info(f"🟥 Caixa (sujo): +{formatar_dinheiro(valor_total)} (Ação ganha {acao['tipo']})")
            except Exception as e:
                logger.error(f"⚠️ Erro ao somar ação no caixa: {e}")

            participantes_botao = await conn.fetch("SELECT user_id FROM participantes_acoes WHERE acao_id=$1", self.acao_id)
            participantes_manuais = await conn.fetch("SELECT nome FROM acoes_participantes_manuais WHERE acao_id=$1", self.acao_id)

        guild = interaction.guild

        # ═══════════════════════════════════════════════════════════════════════
        # DIVISÃO DO VALOR ENTRE PARTICIPANTES
        # Regra: divide entre TODOS os participantes.
        # Só quem tem CARGO SOLDADO tem a parte somada no ACUMULADO COLETIVO
        # dos soldados (não mais no dinheiro_acoes individual).
        # ═══════════════════════════════════════════════════════════════════════
        total_participantes = len(participantes_botao) + len(participantes_manuais)
        valor_por_participante = valor_total // total_participantes if total_participantes > 0 else 0

        logger.info(
            f"💵 Ação #{self.acao_id}: R$ {formatar_dinheiro(valor_total)} / "
            f"{total_participantes} participantes = R$ {formatar_dinheiro(valor_por_participante)} por pessoa"
        )

        membros_soldados = []
        membros_nao_soldados = []
        total_para_soldados = 0

        # Processa participantes do botão
        for p in participantes_botao:
            uid = p["user_id"]
            try:
                member = guild.get_member(int(uid))
                if not member:
                    continue

                tem_soldado = any(r.id == CARGO_SOLDADO_ID for r in member.roles)
                if tem_soldado:
                    membros_soldados.append(member.display_name)
                    total_para_soldados += valor_por_participante
                else:
                    membros_nao_soldados.append(member.display_name)

            except Exception as e:
                logger.error(f"❌ Erro ao processar participante {uid}: {e}")

        # Processa participantes manuais
        for p in participantes_manuais:
            nome_manual = p["nome"]
            if not nome_manual:
                continue
            member_encontrado = None
            try:
                for m in guild.members:
                    if m.display_name.lower() == nome_manual.lower() or m.name.lower() == nome_manual.lower():
                        member_encontrado = m
                        break
            except:
                pass

            if member_encontrado:
                tem_soldado = any(r.id == CARGO_SOLDADO_ID for r in member_encontrado.roles)
                if tem_soldado:
                    membros_soldados.append(member_encontrado.display_name)
                    total_para_soldados += valor_por_participante
                else:
                    membros_nao_soldados.append(nome_manual)
            else:
                logger.warning(f"⚠️ Participante manual '{nome_manual}' não encontrado no servidor")

        # ═══════════════════════════════════════════════════════════════════════
        # SOMA NO ACUMULADO COLETIVO DOS SOLDADOS
        # ═══════════════════════════════════════════════════════════════════════
        if total_para_soldados > 0:
            await somar_total_soldado(total_para_soldados)
            logger.info(f"⚔️ Total coletivo de soldados somado: +{formatar_dinheiro(total_para_soldados)}")

            # Atualiza o painel de todos os soldados
            meta_soldado = await buscar_meta_soldado()
            total_atual = await buscar_total_soldado()
            try:
                cargo_soldado = guild.get_role(CARGO_SOLDADO_ID)
                if cargo_soldado:
                    for m in guild.members:
                        if m.bot:
                            continue
                        if cargo_soldado not in m.roles:
                            continue
                        try:
                            await atualizar_embed_meta(m.id)
                            await asyncio.sleep(0.3)
                        except Exception as e:
                            logger.error(f"❌ Erro ao atualizar soldado {m.display_name}: {e}")
            except Exception as e:
                logger.error(f"❌ Erro ao atualizar painéis dos soldados: {e}")

        # ═══════════════════════════════════════════════════════════════════════
        # MONTA LISTA DE PARTICIPANTES PARA O EMBED
        # ═══════════════════════════════════════════════════════════════════════
        lista_participantes = []
        for p in participantes_botao:
            uid = p["user_id"]
            try:
                member = guild.get_member(int(uid))
                if member:
                    tem_soldado = any(r.id == CARGO_SOLDADO_ID for r in member.roles)
                    emoji_sold = "⚔️" if tem_soldado else "👤"
                    lista_participantes.append(f"{emoji_sold} {member.display_name}")
                else:
                    user = await bot.fetch_user(int(uid))
                    if user:
                        lista_participantes.append(f"👤 {user.display_name or user.name}")
                    else:
                        lista_participantes.append(f"👤 ID: {uid}")
            except:
                lista_participantes.append(f"👤 ID: {uid}")

        for p in participantes_manuais:
            if p["nome"]:
                lista_participantes.append(f"📝 {p['nome']}")

        if not lista_participantes:
            lista_participantes.append("Nenhum participante")

        participantes_texto = "\n".join(lista_participantes)

        embed = discord.Embed(
            title="🏆 ── RESULTADO DA AÇÃO ── 🏆",
            description=f"⚔️ **{acao['tipo']}**",
            color=Cores.SUCESSO,
            timestamp=agora()
        )

        embed.set_author(name="🛡 Vida Rasa 442 • Ações", icon_url=bot.user.display_avatar.url if bot.user else None)
        embed.set_thumbnail(url=bot.user.display_avatar.url if bot.user else None)
        embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)
        embed.add_field(name="🏦 AÇÃO", value=f"```yaml\n{acao['tipo']}\n```", inline=True)
        embed.add_field(name="💰 TOTAL GANHO", value=f"```yaml\n{formatar_dinheiro(valor_total)}\n```", inline=True)
        embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)
        embed.add_field(
            name=f"💵 DIVISÃO ({total_participantes} participantes)",
            value=f"```yaml\n{formatar_dinheiro(valor_por_participante)} por pessoa\n```",
            inline=False
        )
        embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)
        embed.add_field(name="👥 PARTICIPANTES", value=f"```yaml\n{participantes_texto}\n```", inline=False)
        embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)

        if membros_soldados:
            embed.add_field(
                name="⚔️ SOLDADOS (SOMADO NA META COLETIVA)",
                value=f"```yaml\n{chr(10).join(membros_soldados)}\n```\n💵 **+{formatar_dinheiro(total_para_soldados)}** no total coletivo",
                inline=False
            )
        if membros_nao_soldados:
            embed.add_field(
                name="👤 OUTROS (NÃO SOLDADOS)",
                value=f"```yaml\n{chr(10).join(membros_nao_soldados)}\n```",
                inline=False
            )

        embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)
        embed.add_field(name="📌 STATUS", value="```yaml\n✅ AÇÃO FINALIZADA\n🎉 RESULTADO: GANHOU\n```", inline=False)
        embed.set_footer(text=f"🛡 Vida Rasa 442 • ID: {self.acao_id} • Finalizada por {interaction.user.display_name} • {agora().strftime('%d/%m/%Y %H:%M')}", icon_url=bot.user.display_avatar.url if bot.user else None)

        await self.mensagem_original.edit(embed=embed, view=None)
        await enviar_painel_acoes(interaction.guild)

        msg_extra = ""
        if membros_soldados:
            meta_soldado = await buscar_meta_soldado()
            total_atual = await buscar_total_soldado()
            msg_extra = f"\n\n⚔️ **Soldados que receberam:** {len(membros_soldados)}\n💵 **Somado no total coletivo:** {formatar_dinheiro(total_para_soldados)}\n📊 **Progresso da meta coletiva:** {formatar_dinheiro(total_atual)} / {formatar_dinheiro(meta_soldado)}"

        await interaction.followup.send(
            f"✅ **Ação registrada como GANHA!**\n"
            f"💰 Valor total: {formatar_dinheiro(valor_total)}\n"
            f"👥 Dividido entre {total_participantes} participantes\n"
            f"💵 {formatar_dinheiro(valor_por_participante)} por pessoa"
            f"{msg_extra}\n\n"
            f"📌 **Valor total vai para o caixa da facção (dinheiro sujo).**",
            ephemeral=True
        )

