# ────────────────────────────────────────────────────────────────────────────────
# CLASSE: ConfirmarResetAcoesView
# ────────────────────────────────────────────────────────────────────────────────
class ConfirmarResetAcoesView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=60)

    @discord.ui.button(label="✅ CONFIRMAR RESET", style=discord.ButtonStyle.danger, custom_id="confirmar_reset_acoes", emoji="✅")
    async def confirmar(self, interaction: discord.Interaction, button):
        await interaction.response.defer(ephemeral=True)
        pool = await get_pool()
        if not pool:
            await interaction.followup.send("❌ Banco de dados indisponível!", ephemeral=True)
            return
        try:
            total_acoes = 0
            total_participantes = 0
            try:
                async with pool.acquire() as conn:
                    total_acoes = await conn.fetchval("SELECT COUNT(*) FROM acoes_semana") or 0
                    total_participantes = await conn.fetchval("SELECT COUNT(*) FROM participantes_acoes") or 0
            except Exception as e:
                logger.error(f"❌ Erro ao contar ações antes do reset: {e}")

            async with pool.acquire() as conn:
                await conn.execute("DELETE FROM participantes_acoes")
                await conn.execute("DELETE FROM acoes_semana")

            await enviar_painel_acoes(interaction.guild)

            try:
                await registrar_auditoria(
                    user_id=str(interaction.user.id),
                    acao=AuditAcao.RESETAR_ACOES,
                    modulo=AuditModulo.ACOES,
                    item_id=None,
                    item_nome="Reset global de ações",
                    dados_antes={
                        "total_acoes": total_acoes,
                        "total_participantes": total_participantes
                    },
                    dados_depois={
                        "total_acoes": 0,
                        "total_participantes": 0
                    },
                    detalhes=f"Reset GLOBAL — {total_acoes} ações e {total_participantes} participantes deletados"
                )
            except Exception as e:
                logger.error(f"❌ Erro ao auditar reset de ações: {e}")

            embed = discord.Embed(
                title="♻️ AÇÕES RESETADAS COM SUCESSO!",
                description="✅ **Todas as ações foram removidas do sistema.**\n\n"
                            "📌 **O que foi resetado:**\n"
                            "• Todas as ações em andamento ❌\n"
                            "• Todas as ações concluídas ❌\n"
                            "• Todos os participantes ❌\n"
                            "• Todos os limites semanais ❌\n\n"
                            "🔄 **O painel foi atualizado automaticamente.**",
                color=0x2ecc71,
                timestamp=agora()
            )
            embed.set_footer(text=f"Reset realizado por {interaction.user.display_name}")
            await interaction.followup.send(embed=embed, ephemeral=True)
        except Exception as e:
            logger.error(f"❌ Erro ao resetar ações: {e}")
            await interaction.followup.send(f"❌ **Erro ao resetar ações:** {str(e)[:100]}", ephemeral=True)

    @discord.ui.button(label="❌ CANCELAR", style=discord.ButtonStyle.secondary, custom_id="cancelar_reset_acoes", emoji="❌")
    async def cancelar(self, interaction: discord.Interaction, button):
        await interaction.response.send_message("❌ **Reset cancelado.**", ephemeral=True)
        try:
            await interaction.message.delete()
        except:
            pass

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: restaurar_acoes
# ────────────────────────────────────────────────────────────────────────────────
async def restaurar_acoes():
    try:
        canal = bot.get_channel(CANAL_ESCALACOES_ID)
        if not canal:
            logger.error("❌ Canal de escalações não encontrado!")
            return
        contador = 0
        async for msg in canal.history(limit=500):
            if msg.author == bot.user and msg.embeds and len(msg.embeds) > 0:
                embed = msg.embeds[0]
                if embed.footer and "ID:" in embed.footer.text:
                    try:
                        acao_id = safe_int(embed.footer.text.split("ID:")[1].strip().split(" ")[0])
                        acao = await buscar_acao_db(acao_id)
                        if not acao or acao["status"] != "aberta":
                            continue
                        criador_id = int(acao["autor"])
                        if not msg.components:
                            view = AcaoView(acao_id, criador_id)
                            await msg.edit(view=view)
                            contador += 1
                            await asyncio.sleep(1.0)
                    except:
                        pass
        logger.info(f"✅ {contador} ações restauradas com botões!")
    except Exception as e:
        logger.error(f"❌ Erro ao restaurar ações: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: enviar_painel_acoes
# ────────────────────────────────────────────────────────────────────────────────
async def enviar_painel_acoes(guild):
    canal = guild.get_channel(CANAL_ESCALACOES_ID)
    if not canal:
        logger.error("❌ Canal ações não encontrado")
        return
    pool = await get_pool()
    if not pool:
        return

    async with pool.acquire() as conn:
        rows = await conn.fetch("SELECT tipo, COUNT(*) as qtd FROM acoes_semana WHERE status = 'concluida' AND (resultado = 'ganhou' OR resultado = 'perdeu') AND data > NOW() - INTERVAL '7 days' GROUP BY tipo")
    feitas = {r["tipo"]: r["qtd"] for r in rows}

    total_geral_feitas = 0
    total_geral_meta = 0
    
    # ─── BLOCO 1: LIMITES ESPECÍFICOS (Bahamas / Lan Houses) ───
    texto_bahamas = ""
    for acao, limite in LIMITES_ACOES_ESPECIFICOS.items():
        if "Bahamas" in acao or "Museu" in acao:
            qtd_feita = feitas.get(acao, 0)
            restante = max(0, limite - qtd_feita)
            status = "✅ COMPLETO" if qtd_feita >= limite else f"⏳ {restante} rest."
            texto_bahamas += f"• {acao[:15]}: {qtd_feita}/{limite} {status}\n"
            total_geral_feitas += qtd_feita
            total_geral_meta += limite

    for grupo_nome, grupo_dados in GRUPOS_LIMITE_COMPARTILHADO.items():
        acoes_grupo = grupo_dados["acoes"]
        limite = grupo_dados["limite"]
        qtd_feita = sum(feitas.get(acao, 0) for acao in acoes_grupo)
        restante = max(0, limite - qtd_feita)
        status = "✅" if qtd_feita >= limite else f"⏳ {restante} rest."
        texto_bahamas += f"• {grupo_nome}: {qtd_feita}/{limite} {status}\n"
        total_geral_feitas += qtd_feita
        total_geral_meta += limite

    # ─── BLOCO 2: OUTRAS CATEGORIAS (Complexo) ───
    texto_complexo = ""
    for categoria, dados in CATEGORIAS_ACOES.items():
        if categoria == "Bahamas":
            continue # Já tratamos acima
        limite = dados["limite"]
        acoes = dados["acoes"]
        emoji = dados["emoji"]
        qtd_feita = sum(feitas.get(acao, 0) for acao in acoes)
        total_geral_feitas += qtd_feita
        
        if limite is None:
            texto_complexo += f"• {emoji} {categoria[:12]}: {qtd_feita} (ILIMITADO)\n"
        else:
            total_geral_meta += limite
            restante = max(0, limite - qtd_feita)
            status = "✅" if qtd_feita >= limite else f"⏳ {restante} rest."
            texto_complexo += f"• {emoji} {categoria[:12]}: {qtd_feita}/{limite} {status}\n"

    # ─── EMBED PREMIUM ───
    embed = discord.Embed(
        title="⚔️ ── CENTRAL DE AÇÕES ── ⚔️",
        description="**VDR 442 • Escalações e Limites**\n*Acompanhe o progresso das ações da semana*",
        color=0xC0392B,
        timestamp=agora()
    )
    embed.set_thumbnail(url=bot.user.display_avatar.url if bot.user else None)

    embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)

    # Adiciona os limites em campos separados para não estourar o limite de 1024 do Discord
    if texto_complexo:
        embed.add_field(
            name="🏙️ LIMITES DO COMPLEXO",
            value=f"```yaml\n{texto_complexo}```",
            inline=False
        )

    if texto_bahamas:
        embed.add_field(
            name="🏝️ LIMITES DE BAHAMAS",
            value=f"```yaml\n{texto_bahamas}```",
            inline=False
        )

    # Barra de progresso geral
    texto_progresso = ""
    if total_geral_meta > 0:
        porcentagem = int((total_geral_feitas / total_geral_meta) * 100)
        barra = "▓" * int((porcentagem / 100) * 10) + "░" * (10 - int((porcentagem / 100) * 10))
        texto_progresso = f"{total_geral_feitas}/{total_geral_meta} ações realizadas\n{barra} {porcentagem}%"

    embed.add_field(name="━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━", value="", inline=False)
    embed.add_field(
        name="📊 PROGRESSO GERAL DA SEMANA",
        value=f"```yaml\n{texto_progresso}```" if texto_progresso else "```yaml\nNenhuma meta de ação definida\n```",
        inline=False
    )

    embed.set_footer(text=f"🛡 Vida Rasa 442 • Atualizado em {agora().strftime('%d/%m/%Y às %H:%M')}", icon_url=bot.user.display_avatar.url if bot.user else None)

    view = PainelAcoesView()
    await enviar_ou_atualizar_painel("painel_acoes", CANAL_ESCALACOES_ID, embed, view)

