# CLASSE: RelatorioVendasModal
# ────────────────────────────────────────────────────────────────────────────────
class RelatorioVendasModal(discord.ui.Modal, title="📅 RELATÓRIO DE VENDAS"):
    data_inicio = discord.ui.TextInput(label="📅 Data INÍCIO (DD/MM/AAAA)", placeholder="Ex: 01/09/2026", required=True)
    data_fim = discord.ui.TextInput(label="📅 Data FIM (DD/MM/AAAA)", placeholder="Ex: 30/09/2026", required=True)

    async def on_submit(self, interaction: discord.Interaction):
        await interaction.response.defer(ephemeral=True)

        data_inicio_str = self.data_inicio.value.strip()
        data_fim_str = self.data_fim.value.strip()

        try:
            data_inicio = datetime.strptime(data_inicio_str, "%d/%m/%Y").replace(hour=0, minute=0, second=0)
            data_fim = datetime.strptime(data_fim_str, "%d/%m/%Y").replace(hour=23, minute=59, second=59)
        except:
            await interaction.followup.send("❌ Formato inválido! Use DD/MM/AAAA", ephemeral=True)
            return

        if data_fim < data_inicio:
            await interaction.followup.send("❌ Data FIM deve ser depois da data INÍCIO!", ephemeral=True)
            return

        pool = await get_pool()
        if not pool:
            await interaction.followup.send("❌ Banco de dados indisponível!", ephemeral=True)
            return

        async with pool.acquire() as conn:
            rows = await conn.fetch(
                """SELECT user_id, SUM(valor) as total, COUNT(*) as quantidade
                FROM vendas 
                WHERE TO_DATE(data, 'DD/MM/YYYY') BETWEEN $1::date AND $2::date
                GROUP BY user_id 
                ORDER BY total DESC""",
                data_inicio, data_fim
            )
            total_geral = await conn.fetchval(
                "SELECT COALESCE(SUM(valor), 0) FROM vendas WHERE TO_DATE(data, 'DD/MM/YYYY') BETWEEN $1::date AND $2::date",
                data_inicio, data_fim
            )

        if not rows:
            await interaction.followup.send(f"📭 Nenhuma venda no período **{data_inicio_str}** a **{data_fim_str}**", ephemeral=True)
            return

        embed = discord.Embed(
            title="📊 RELATÓRIO DE VENDAS",
            description=f"📅 **Período:** {data_inicio_str} a {data_fim_str}",
            color=Cores.VENDA,
            timestamp=agora()
        )
        embed.set_author(name="🛡 Vida Rasa 442 • Relatório de Vendas")

        texto_atual = ""
        parte = 1
        for i, row in enumerate(rows, 1):
            user = await pegar_usuario(int(row["user_id"]))
            nome = user.display_name if user else row["user_id"]
            linha = f"**{i}.** {nome}\n"
            linha += f"   💰 Vendas: **{formatar_dinheiro(row['total'])}**\n"
            linha += f"   📦 Pedidos: **{row['quantidade']}**\n\n"

            if len(texto_atual) + len(linha) > 1000:
                embed.add_field(name=f"👥 VENDEDORES (Parte {parte})", value=texto_atual, inline=False)
                texto_atual = ""
                parte += 1

            texto_atual += linha

        if texto_atual:
            embed.add_field(name=f"👥 VENDEDORES (Parte {parte})", value=texto_atual, inline=False)

        embed.add_field(name="💰 TOTAL GERAL", value=formatar_dinheiro(total_geral), inline=True)
        embed.add_field(name="📦 TOTAL DE PEDIDOS", value=sum(r["quantidade"] for r in rows), inline=True)
        embed.set_footer(text="Relatório gerado pelo sistema VDR")

        await interaction.followup.send(embed=embed, ephemeral=False)

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: finalizar_e_mover_pedido
# ────────────────────────────────────────────────────────────────────────────────
async def finalizar_e_mover_pedido(
    interaction: discord.Interaction,
    mensagem_original: discord.Message,
    pedido_numero: int,
    pt: int,
    sub: int,
    transferido_para: str = None,
    tipo: str = "finalizado"
):
    try:
        embed_original = mensagem_original.embeds[0]
        dados = await extrair_dados_pedido_do_embed(embed_original)

        if pedido_numero:
            dados["pedido_numero"] = pedido_numero
        if pt:
            dados["pt"] = pt
        if sub:
            dados["sub"] = sub
        if transferido_para:
            dados["transferido_para"] = transferido_para

        deletado = False
        try:
            await mensagem_original.delete()
            deletado = True
            logger.info(f"🗑️ Pedido #{dados['pedido_numero']:04d} removido do canal de encomendas")
        except discord.NotFound:
            deletado = True
        except Exception as e:
            logger.warning(f"⚠️ Não foi possível deletar mensagem original: {e}")

        if deletado:
            if tipo == "cancelado":
                await marcar_pedido_finalizado(dados["pedido_numero"], tipo="cancelado")
            else:
                await marcar_pedido_finalizado(dados["pedido_numero"], tipo="finalizado")
        else:
            logger.warning(
                f"⚠️ Pedido #{dados['pedido_numero']:04d} NÃO foi marcado no banco "
                f"(deleção da mensagem falhou). Verifique permissões."
            )
            try:
                await interaction.followup.send(
                    f"⚠️ **Atenção:** não foi possível deletar a mensagem original do pedido "
                    f"#{dados['pedido_numero']:04d}. O banco NÃO foi marcado como finalizado. "
                    f"Verifique as permissões do bot no canal Encomendas.",
                    ephemeral=True
                )
            except:
                pass

        await enviar_embed_pedido_finalizado(
            pedido_numero=dados["pedido_numero"],
            pt=dados["pt"],
            sub=dados["sub"],
            organizacao=dados["organizacao"],
            vendedor_nome=dados["vendedor"],
            pago_por=dados["pago_por"],
            pago_em=dados["pago_em"],
            entregue_por=dados["entregue_por"],
            entregue_em=dados["entregue_em"],
            transferido_para=dados["transferido_para"],
            transferido_por=dados["transferido_por"],
            transferido_em=dados["transferido_em"],
            cancelado_por=dados["cancelado_por"],
            cancelado_em=dados["cancelado_em"],
            tipo=tipo
        )

        try:
            pool = await get_pool()
            if pool:
                async with pool.acquire() as conn:
                    await conn.execute(
                        "DELETE FROM botoes_persistentes WHERE mensagem_id = $1",
                        str(mensagem_original.id)
                    )
        except Exception as e:
            logger.error(f"❌ Erro ao limpar botões persistentes: {e}")

        try:
            await enviar_painel_vendas()
            await enviar_painel_fabricacao()
            await enviar_painel_caixa()
        except Exception as e:
            logger.error(f"❌ Erro ao atualizar painéis: {e}")

        return True

    except Exception as e:
        logger.error(f"❌ Erro em finalizar_e_mover_pedido: {e}")
        return False

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: restaurar_botoes_vendas
# ────────────────────────────────────────────────────────────────────────────────
async def restaurar_botoes_vendas():
    try:
        canal = bot.get_channel(CANAL_ENCOMENDAS_ID)
        if not canal:
            logger.error("❌ Canal de encomendas não encontrado!")
            return
        contador_ativos = 0
        contador_ignorados = 0
        async for msg in canal.history(limit=500):
            if msg.author == bot.user and msg.embeds and len(msg.embeds) > 0:
                titulo = msg.embeds[0].title if msg.embeds[0].title else ""
                if "ENTREGA" in titulo.upper() or "ENCOMENDA" in titulo.upper() or "VENDA" in titulo.upper():
                    embed = msg.embeds[0]
                    pago = False
                    entregue = False
                    cancelado = False
                    concluida = False
                    transferencia_confirmada = False
                    if "VENDA CONCLUÍDA" in titulo.upper():
                        concluida = True
                        pago = True
                        entregue = True
                    for field in embed.fields:
                        if field.name == "📌 STATUS DO PEDIDO" or field.name == "📌 Status":
                            valor = field.value
                            if "TRANSFERÊNCIA CONFIRMADA" in valor:
                                transferencia_confirmada = True
                            if "💰" in valor or "Pago" in valor:
                                pago = True
                            if "✅" in valor or "Entregue" in valor:
                                entregue = True
                            if "❌" in valor or "cancelado" in valor.lower():
                                cancelado = True
                            break

                    if cancelado or concluida or transferencia_confirmada:
                        contador_ignorados += 1
                        continue

                    entrega_id = None
                    if embed.footer:
                        texto_footer = embed.footer.text
                        if "ID:" in texto_footer:
                            try:
                                parte_id = texto_footer.split("ID:")[1].strip().split(" ")[0]
                                entrega_id = safe_int(parte_id)
                            except:
                                pass
                    total_entregas = 1
                    entrega_atual = 1
                    if embed.description:
                        if "entregas no total" in embed.description:
                            try:
                                total_entregas = safe_int(embed.description.split("tem")[1].split("entregas")[0].strip())
                            except:
                                pass
                    if "ENTREGA" in titulo:
                        try:
                            parte = titulo.split("ENTREGA")[1].strip().split("/")[0].strip()
                            entrega_atual = safe_int(parte)
                        except:
                            pass
                    valor_total = 0
                    pt = 0
                    sub = 0
                    pedido_numero = safe_int(titulo.split("#")[1]) if "#" in titulo else 0
                    for field in embed.fields:
                        if field.name == "💰 VALOR TOTAL" or field.name == "💰 Valor (esta entrega)" or field.name == "💰 Valor":
                            try:
                                valor_total = safe_int(field.value.replace("R$", "").replace(".", "").replace(",", "").strip())
                            except:
                                pass
                        if field.name == "🔫 PT":
                            try:
                                pt = int(field.value.split(" munições")[0].replace(".", "").replace(",", ""))
                            except:
                                pass
                        if field.name == "🔫 SUB":
                            try:
                                sub = int(field.value.split(" munições")[0].replace(".", "").replace(",", ""))
                            except:
                                pass
                    view = StatusView(
                        disabled=False,
                        entrega_id=entrega_id,
                        total_entregas=total_entregas,
                        entrega_atual=entrega_atual,
                        pago_ja_clicado=pago,
                        mensagem_original=msg,
                        transferencia_confirmada=False,
                        valor_total=valor_total,
                        pt=pt,
                        sub=sub,
                        pedido_numero=pedido_numero
                    )
                    await safe_request(msg.edit, view=view)
                    contador_ativos += 1
                    await asyncio.sleep(0.5)

        logger.info(f"✅ {contador_ativos} pedidos EM ABERTO com botões restaurados")
        logger.info(f"⏭️ {contador_ignorados} pedidos FINALIZADOS/CANCELADOS ignorados")
    except Exception as e:
        logger.error(f"❌ Erro ao restaurar botões de vendas: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: recriar_mensagens_vendas
# ────────────────────────────────────────────────────────────────────────────────
async def recriar_mensagens_vendas():
    try:
        canal = bot.get_channel(CANAL_ENCOMENDAS_ID)
        if not canal:
            logger.error("❌ Canal de encomendas não encontrado!")
            return
        contador_recriados = 0
        contador_ignorados = 0
        async for msg in canal.history(limit=500):
            if msg.author == bot.user and msg.embeds and len(msg.embeds) > 0:
                titulo = msg.embeds[0].title if msg.embeds[0].title else ""
                if "ENTREGA" in titulo.upper() or "ENCOMENDA" in titulo.upper() or "VENDA" in titulo.upper():
                    embed = msg.embeds[0]
                    concluida = False
                    cancelada = False
                    transferencia_confirmada = False
                    for field in embed.fields:
                        if field.name == "📌 STATUS DO PEDIDO" or field.name == "📌 Status":
                            valor = field.value
                            if "CONCLUÍDA" in valor.upper():
                                concluida = True
                            if "TRANSFERÊNCIA CONFIRMADA" in valor:
                                transferencia_confirmada = True
                            if "💰" in valor and "✅" in valor:
                                concluida = True
                            if "CANCELADO" in valor.upper() or "CANCELADA" in valor.upper():
                                cancelada = True
                            if "❌" in valor:
                                cancelada = True
                            break
                    if concluida or cancelada or transferencia_confirmada:
                        contador_ignorados += 1
                        continue

                    if msg.components:
                        contador_ignorados += 1
                        continue
                    entrega_id = None
                    if embed.footer:
                        texto_footer = embed.footer.text
                        if "ID:" in texto_footer:
                            try:
                                parte_id = texto_footer.split("ID:")[1].strip().split(" ")[0]
                                entrega_id = safe_int(parte_id)
                            except:
                                pass
                    total_entregas = 1
                    if embed.description:
                        if "entregas no total" in embed.description:
                            try:
                                total_entregas = safe_int(embed.description.split("tem")[1].split("entregas")[0].strip())
                            except:
                                pass
                    view = StatusView(
                        disabled=False,
                        entrega_id=entrega_id,
                        total_entregas=total_entregas,
                        mensagem_original=msg
                    )
                    await safe_request(msg.edit, view=view)
                    contador_recriados += 1
                    await asyncio.sleep(0.5)
        logger.info(f"✅ {contador_recriados} mensagens de venda recriadas!")
        logger.info(f"⏭️ {contador_ignorados} vendas concluídas/canceladas (IGNORADAS)")
    except Exception as e:
        logger.error(f"❌ Erro ao recriar mensagens de vendas: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: enviar_painel_vendas
