# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: carregar_estoque
# ────────────────────────────────────────────────────────────────────────────────
async def carregar_estoque():
    pool = await get_pool()
    if not pool:
        return {"PT": 0, "SUB": 0}
    try:
        async with pool.acquire() as conn:
            rows = await conn.fetch("SELECT tipo, quantidade FROM estoque_municoes")
        estoque = {"PT": 0, "SUB": 0}
        for row in rows:
            estoque[row["tipo"]] = row["quantidade"]
        return estoque
    except Exception as e:
        logger.error(f"❌ Erro ao carregar estoque: {e}")
        return {"PT": 0, "SUB": 0}

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: atualizar_estoque
# ────────────────────────────────────────────────────────────────────────────────
async def atualizar_estoque(tipo, quantidade, operacao="adicionar"):
    pool = await get_pool()
    if not pool:
        return
    try:
        async with pool.acquire() as conn:
            if operacao == "adicionar":
                await conn.execute(
                    "UPDATE estoque_municoes SET quantidade = quantidade + $1, ultima_atualizacao = NOW() WHERE tipo = $2",
                    quantidade, tipo
                )
            else:
                await conn.execute(
                    "UPDATE estoque_municoes SET quantidade = quantidade - $1, ultima_atualizacao = NOW() WHERE tipo = $2 AND quantidade >= $1",
                    quantidade, tipo
                )
    except Exception as e:
        logger.error(f"❌ Erro ao atualizar estoque: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: carregar_estoque_polvora
# ────────────────────────────────────────────────────────────────────────────────
async def carregar_estoque_polvora():
    pool = await get_pool()
    if not pool:
        return 0
    try:
        async with pool.acquire() as conn:
            row = await conn.fetchrow("SELECT quantidade FROM estoque_polvora WHERE id = 1")
            return row["quantidade"] if row else 0
    except Exception as e:
        logger.error(f"❌ Erro ao carregar estoque de pólvora: {e}")
        return 0

