# FUNÇÃO: enviar_aviso_meta_nao_batida
# ────────────────────────────────────────────────────────────────────────────────
async def enviar_aviso_meta_nao_batida(user_id, valor_original, valor_divida, motivo="NAO_BATEU", tipo="dinheiro"):
    try:
        if str(user_id) not in metas_cache:
            return False

        canal_id = metas_cache[str(user_id)]["canal_id"]
        canal = bot.get_channel(canal_id)
        if not canal:
            logger.warning(f"⚠️ Canal de meta não encontrado para {user_id}")
            return False

        guild = bot.get_guild(GUILD_ID)
        member = guild.get_member(int(user_id)) if guild else None
        nome = member.display_name if member else f"ID: {user_id}"

        if tipo == "polvora":
            valor_original_str = f"{fmt_num(valor_original)} PÓLVORAS"
            valor_divida_str = f"{fmt_num(valor_divida)} PÓLVORAS"
            emoji_tipo = "🧨"
            nome_tipo = "PÓLVORA"
        else:
            valor_original_str = formatar_dinheiro(valor_original)
            valor_divida_str = formatar_dinheiro(valor_divida)
            emoji_tipo = "💰"
            nome_tipo = "DINHEIRO SUJO"

        if motivo == "NAO_BATEU":
            embed = discord.Embed(
                title=f"🚨 ATENÇÃO! META DE {nome_tipo} NÃO BATIDA! 🚨",
                description=(
                    f"```diff\n"
                    f"- VOCÊ NÃO BATEU A META DA SEMANA ANTERIOR!\n"
                    f"```\n"
                    f"**{nome.upper()}**\n\n"
                    f"```yaml\n"
                    f"{emoji_tipo} META DA SEMANA: {valor_original_str}\n"
                    f"{emoji_tipo} SUA DÍVIDA ACUMULADA: {valor_divida_str}\n"
                    f"```\n\n"
                    f"🔴 **ATENÇÃO:**\n"
                    f"```diff\n"
                    f"- A DÍVIDA CRESCE A CADA SEMANA NÃO PAGA!\n"
                    f"- PAGUE PARA LIMPAR SEU NOME!\n"
                    f"- SE NÃO PAGAR, PODE PERDER O SET!\n"
                    f"```\n\n"
                    f"💪 **CORRA ATRÁS DO PREJUÍZO!**"
                ),
                color=0xE74C3C,
                timestamp=agora()
            )
            embed.set_author(
                name="🛡 VIDA RASA 442 • SISTEMA DE METAS",
                icon_url=bot.user.display_avatar.url if bot.user else None
            )
            if member and member.display_avatar:
                embed.set_thumbnail(url=member.display_avatar.url)
            embed.set_footer(
                text=f"⚠️ AVISO AUTOMÁTICO • {agora().strftime('%d/%m/%Y %H:%M')}",
                icon_url=bot.user.display_avatar.url if bot.user else None
            )

        else:
            embed = discord.Embed(
                title="💀 VOCÊ PERDEU O SET! 💀",
                description=(
                    f"```diff\n"
                    f"- VOCÊ NÃO PAGOU SUA DÍVIDA!\n"
                    f"```\n"
                    f"**{nome.upper()}**\n\n"
                    f"```yaml\n"
                    f"{emoji_tipo} META ORIGINAL: {valor_original_str}\n"
                    f"{emoji_tipo} DÍVIDA: {valor_divida_str}\n"
                    f"```\n\n"
                    f"🔴 **CONSEQUÊNCIA:**\n"
                    f"```diff\n"
                    f"- VOCÊ PERDEU O SET DO TABLET!\n"
                    f"- PROCURE A GERÊNCIA PARA MAIS INFORMAÇÕES.\n"
                    f"```\n\n"
                    f"⚠️ **AVISO ENVIADO À GERÊNCIA.**"
                ),
                color=0x8B0000,
                timestamp=agora()
            )
            embed.set_author(
                name="🛡 VIDA RASA 442 • SISTEMA DE METAS",
                icon_url=bot.user.display_avatar.url if bot.user else None
            )
            if member and member.display_avatar:
                embed.set_thumbnail(url=member.display_avatar.url)
            embed.set_footer(
                text=f"⚠️ AVISO AUTOMÁTICO • {agora().strftime('%d/%m/%Y %H:%M')}",
                icon_url=bot.user.display_avatar.url if bot.user else None
            )

        await canal.send(
            content=f"🔔 {member.mention if member else ''} **AVISO IMPORTANTE!**",
            embed=embed
        )

        logger.info(f"📢 Aviso de meta não batida ({tipo}) enviado para {nome} (motivo: {motivo})")
        return True

    except Exception as e:
        logger.error(f"❌ Erro ao enviar aviso de meta não batida: {e}")
        return False

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: atualizar_categoria_meta
# ────────────────────────────────────────────────────────────────────────────────
async def atualizar_categoria_meta(member):
    try:
        if str(member.id) not in metas_cache:
            return
        dados = metas_cache[str(member.id)]
        canal = member.guild.get_channel(dados["canal_id"])
        if not canal:
            return

        nome_correto = f"📁・{member.display_name.lower().replace(' ', '-')}"
        if canal.name.lower() != nome_correto.lower():
            try:
                await canal.edit(name=nome_correto)
                logger.info(f"✏️ Sala renomeada em atualizar_categoria_meta: {canal.name} → {nome_correto}")
            except Exception as e:
                logger.error(f"❌ Erro ao renomear sala: {e}")

        nova_categoria_id = await obter_categoria_meta_async(member)
        if not nova_categoria_id:
            return
        nova_categoria = member.guild.get_channel(nova_categoria_id)
        if not nova_categoria:
            return
        if canal.category_id == nova_categoria_id:
            return
        await canal.edit(category=nova_categoria)
        await atualizar_embed_meta(member.id)
    except Exception as e:
        logger.error(f"❌ Erro ao atualizar categoria de {member.name}: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: fixar_painel_meta_no_final (DELETA + RECRIA IMEDIATAMENTE)
# ────────────────────────────────────────────────────────────────────────────────
async def fixar_painel_meta_no_final(user_id):
    try:
        if str(user_id) not in metas_cache:
            return
        dados = metas_cache[str(user_id)]
        canal = bot.get_channel(dados["canal_id"])
        if not canal:
            return

        mensagem_painel = None
        async for msg in canal.history(limit=30):
            if msg.author == bot.user and msg.embeds and len(msg.embeds) > 0:
                if msg.embeds[0].title and "META SEMANAL" in msg.embeds[0].title.upper():
                    mensagem_painel = msg
                    break

        if not mensagem_painel:
            await atualizar_embed_meta(user_id)
            return

        ultima_msg = None
        async for msg in canal.history(limit=1):
            ultima_msg = msg
            break

        if ultima_msg and ultima_msg.id == mensagem_painel.id:
            return

        try:
            await mensagem_painel.delete()
        except Exception as e:
            logger.error(f"Erro ao deletar painel: {e}")
            return

        await asyncio.sleep(0.5)

        try:
            await atualizar_embed_meta(user_id)
            logger.info(f"✅ Painel de meta do user {user_id} recriado no final")
        except Exception as e:
            logger.error(f"❌ Erro ao recriar painel de meta: {e}")
    except Exception as e:
        logger.error(f"❌ Erro ao fixar painel: {e}")
