# CLASSE: VerDividasButton
# ────────────────────────────────────────────────────────────────────────────────
class VerDividasButton(discord.ui.Button):
    def __init__(self):
        super().__init__(
            label="📋 Ver Dívidas",
            style=discord.ButtonStyle.success,
            custom_id="ver_dividas_btn",
            emoji="📋",
            row=1
        )

    async def callback(self, interaction: discord.Interaction):
        is_admin = interaction.user.guild_permissions.administrator
        is_gerente = any(
            r.id in [CARGO_GERENTE_ID, CARGO_GERENTE_GERAL_ID, CARGO_GERENTE_MECANICA_ID]
            for r in interaction.user.roles
        )
        if not is_admin and not is_gerente:
            await interaction.response.send_message(
                "❌ Apenas **ADM** ou **GERENTES** podem ver as dívidas!",
                ephemeral=True
            )
            return

        await interaction.response.defer(ephemeral=True)

        dividas = await listar_dividas_ativas()

        if not dividas:
            await interaction.followup.send("✅ **Nenhuma dívida ativa no momento!**", ephemeral=True)
            return

        por_usuario = {}
        for d in dividas:
            uid = d["user_id"]
            tipo = d["tipo"] or "dinheiro"
            if uid not in por_usuario:
                por_usuario[uid] = {"dinheiro": 0, "polvora": 0, "total_dinheiro": 0, "total_polvora": 0}
            if tipo == "polvora":
                por_usuario[uid]["polvora"] += d["valor_divida"]
                por_usuario[uid]["total_polvora"] += 1
            else:
                por_usuario[uid]["dinheiro"] += d["valor_divida"]
                por_usuario[uid]["total_dinheiro"] += 1

        embed = discord.Embed(
            title="📋 ── DÍVIDAS ATIVAS ── 📋",
            description=f"📊 Total: **{len(dividas)}** dívida(s) | **{len(por_usuario)}** membro(s)",
            color=0xE74C3C,
            timestamp=agora()
        )

        ordenado = sorted(
            por_usuario.items(),
            key=lambda x: (x[1]["dinheiro"] + x[1]["polvora"] * 100),
            reverse=True
        )

        texto = ""
        for uid, dados in ordenado[:30]:
            member = interaction.guild.get_member(int(uid))
            nome = member.display_name if member else f"ID: {uid}"
            texto += f"**{nome}**\n"
            if dados["dinheiro"] > 0:
                texto += f"   💰 Dinheiro: {formatar_dinheiro(dados['dinheiro'])}\n"
            if dados["polvora"] > 0:
                texto += f"   🧨 Pólvora: {fmt_num(dados['polvora'])} unidades\n"
            texto += "\n"

        if len(por_usuario) > 30:
            texto += f"\n*... e mais {len(por_usuario) - 30} membros*"

        embed.add_field(name="👥 MEMBROS EM DÍVIDA", value=texto[:1024], inline=False)
        embed.set_footer(
            text=f"🛡 Vida Rasa 442 • {agora().strftime('%d/%m/%Y %H:%M')}",
            icon_url=bot.user.display_avatar.url if bot.user else None
        )

        await interaction.followup.send(embed=embed, ephemeral=True)

# ────────────────────────────────────────────────────────────────────────────────
# CLASSE: RemoverDividaSelect
# ────────────────────────────────────────────────────────────────────────────────
class RemoverDividaSelect(discord.ui.Select):
    def __init__(self, dividas, guild):
        options = []
        # Agrupa por usuário para não duplicar no menu
        usuarios = {}
        for d in dividas:
            uid = d["user_id"]
            if uid not in usuarios:
                usuarios[uid] = 0
            usuarios[uid] += d["valor_divida"]
        
        # Ordena pelas maiores dívidas primeiro
        usuarios_ordenados = sorted(usuarios.items(), key=lambda x: x[1], reverse=True)

        for uid, total in usuarios_ordenados[:25]: # Discord limita a 25 opções
            # Puxa o membro do servidor para pegar o apelido
            member = guild.get_member(int(uid)) if guild else None
            nome_exibicao = member.display_name if member else f"ID: {uid}"
            
            options.append(discord.SelectOption(
                label=nome_exibicao[:100], # Limite do Discord para label
                description=f"Dívida total: {formatar_dinheiro(total)}",
                value=str(uid)
            ))
        
        if not options:
            options.append(discord.SelectOption(label="Nenhuma dívida", value="none"))

        super().__init__(placeholder="Selecione o membro para limpar as dívidas...", min_values=1, max_values=1, options=options)

    async def callback(self, interaction: discord.Interaction):
        if self.values[0] == "none":
            await interaction.response.send_message("📭 Nenhuma dívida para remover.", ephemeral=True)
            return

        user_id = self.values[0]
        member = interaction.guild.get_member(int(user_id))
        nome = member.mention if member else f"<@{user_id}>"

        pool = await get_pool()
        if pool:
            async with pool.acquire() as conn:
                await conn.execute("UPDATE metas_dividas SET pago = true, data_pagamento = NOW() WHERE user_id = $1 AND pago = false", str(user_id))
        
        await atualizar_embed_meta(int(user_id))
        await enviar_painel_relatorio_metas() # Atualiza o painel principal

        embed = discord.Embed(
            title="✅ DÍVIDAS LIMPADAS",
            description=f"As dívidas de {nome} foram removidas com sucesso.",
            color=0x2ecc71,
            timestamp=agora()
        )
        await interaction.response.edit_message(embed=embed, view=None)

