            embed.add_field(name="📊 RESUMO GERAL", value=f"```yaml\n👥 Grupos ativos: {len(grupos)}\n🔫 PT vendido: {fmt_num(total_pt)} pacotes\n🔫 SUB vendido: {fmt_num(total_sub)} pacotes\n```", inline=False)
