# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: carregar_dados_iniciais
# ────────────────────────────────────────────────────────────────────────────────
async def carregar_dados_iniciais():
    try:
        rows = await carregar_metas_db()
        for r in rows:
            metas_cache[str(r["user_id"])] = {
                "canal_id": int(r["canal_id"]),
                "dinheiro": r["dinheiro"],
                "acao": r["acao"],
                "dinheiro_acoes": r.get("dinheiro_acoes") or 0,
                "saldo_excedente": r.get("saldo_excedente") or 0
            }
    except Exception as e:
        logger.error(f"Erro ao carregar metas: {e}")
    await restaurar_producoes()
    if not hasattr(bot, "heartbeat_producao_started"):
        bot.loop.create_task(heartbeat_producao_loop())
        bot.heartbeat_producao_started = True

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: restaurar_botoes_metas
# ────────────────────────────────────────────────────────────────────────────────
async def restaurar_botoes_metas():
    try:
        guild = bot.get_guild(GUILD_ID)
        if not guild:
            logger.error("❌ Guild não encontrada!")
            return 0
        await carregar_metas_cache()
        contador = 0
        for uid, dados in list(metas_cache.items()):
            canal = guild.get_channel(dados["canal_id"])
            if not canal:
                continue
            try:
                mensagem_encontrada = False
                eh_v2 = False

                async for msg in canal.history(limit=30):
                    if msg.author != bot.user:
                        continue

                    # Detecta V2 (components com custom_id v2_)
                    if msg.components:
                        for row_comp in msg.components:
                            for c in getattr(row_comp, "children", []):
                                cid = getattr(c, "custom_id", "") or ""
                                if cid.startswith("v2_"):
                                    mensagem_encontrada = True
                                    eh_v2 = True
                                    break
                            if eh_v2:
                                break

                    if eh_v2:
                        break

                # Se não achou nenhum painel (ou achou V1 legado) → recria V2
                if not mensagem_encontrada:
                    await atualizar_embed_meta(int(uid))
                    contador += 1
                    await asyncio.sleep(1.5)
            except Exception as e:
                logger.error(f"❌ Erro ao restaurar meta {uid}: {e}")
        logger.info(f"✅ {contador} painéis de metas restaurados com botões!")
        return contador
    except Exception as e:
        logger.error(f"❌ Erro ao restaurar botões das metas: {e}")
        return 0

# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: enviar_paineis_iniciais
# ────────────────────────────────────────────────────────────────────────────────
async def enviar_paineis_iniciais(guild):
    try:
        paineis = [
            ("Registro", enviar_painel_registro),
            ("Fabricação", enviar_painel_fabricacao),
            ("Lives", enviar_painel_lives),
            ("Lavagem", enviar_painel_lavagem),
            ("Vendas", enviar_painel_vendas),
            ("Relatório Financeiro", enviar_painel_relatorio_financeiro),
            ("Registrar Compra", enviar_painel_registrar_compra),
            ("Solicitar Sala", enviar_painel_solicitar_sala),
            ("Botão Ausência", enviar_painel_ausencia),
            ("Relatório Metas", enviar_painel_relatorio_metas),
            ("Baú", enviar_painel_bau),
            ("Armas", enviar_painel_armas),
            ("Avisos", enviar_painel_avisos),
            ("Grupos", enviar_painel_grupos),
            ("Mensagens", enviar_painel_mensagens),
            ("Auditoria", enviar_painel_auditoria),
            ("Caixa", enviar_painel_caixa),
            ("Empréstimos", enviar_painel_emprestimos),
            ("Doações", enviar_painel_doacoes),
        ]
        for i, (nome, func) in enumerate(paineis):
            try:
                await func()
                if i < len(paineis) - 1:
                    await asyncio.sleep(2)
            except Exception as e:
                logger.error(f"❌ Erro ao enviar painel {nome}: {e}")
                await asyncio.sleep(3)
        if guild:
            try:
                await enviar_painel_acoes(guild)
                await asyncio.sleep(2)
            except Exception as e:
                logger.error(f"❌ Erro ao enviar painel de ações: {e}")
        try:
            await recriar_painel_grupos()
        except Exception as e:
            logger.error(f"❌ Erro ao forçar atualização grupos: {e}")
    except Exception as e:
        logger.error(f"❌ Erro geral ao enviar painéis: {e}")

# ────────────────────────────────────────────────────────────────────────────────
# EVENTO: on_ready
# ────────────────────────────────────────────────────────────────────────────────
@bot.event
async def on_ready():
    global http_session
    if hasattr(bot, "ja_iniciado"):
        return
    bot.ja_iniciado = True
    logger.info("🔄 Iniciando configuração do bot...")
    logger.info(f"✅ Logado como {bot.user}")
    if not http_session:
        http_session = aiohttp.ClientSession()
    db_pool = await conectar_db()
    if not db_pool:
        logger.critical("❌ Não foi possível conectar ao banco de dados!")
        return
    guild = bot.get_guild(GUILD_ID)
    if guild:
        try:
            await guild.chunk()
        except Exception as e:
            logger.error(f"Erro ao carregar membros: {e}")
    logger.info(f"🕒 Horário Brasília: {agora().strftime('%d/%m/%Y %H:%M:%S')}")
    await carregar_metas_cache()
    await iniciar_tarefas_background()
    bot.loop.create_task(limpeza_cache_periodica())
    bot.loop.create_task(health_check_avancado())
    if not hasattr(bot, "edit_worker_started"):
        bot.loop.create_task(edit_worker())
        bot.edit_worker_started = True
    await carregar_dados_iniciais()
    await enviar_paineis_iniciais(guild)
    await BotaoPersistente.restaurar_botoes()
    await restaurar_botoes_vendas()
    await restaurar_acoes()
    await restaurar_botoes_metas()
    await setup_status()
    if not hasattr(bot, "heartbeat_producao_started"):
        bot.loop.create_task(heartbeat_producao_loop())
        bot.heartbeat_producao_started = True
    # ═══════════════════════════════════════════════════════════════════════════
    # RESTAURA PAINÉIS COMO ÚLTIMO EM TODOS OS CANAIS
    # ═══════════════════════════════════════════════════════════════════════════
    try:
        pool = await get_pool()
        if pool:
            async with pool.acquire() as conn:
                paineis_rows = await conn.fetch("SELECT DISTINCT canal_id FROM paineis_ultimos WHERE ativo = true")
            for row in paineis_rows:
                canal_id = int(row["canal_id"])
                canal = bot.get_channel(canal_id)
                if canal:
                    try:
                        await verificar_e_mover_paineis(canal)
                        await asyncio.sleep(1)
                    except Exception as e:
                        logger.error(f"❌ Erro ao restaurar painel do canal {canal_id}: {e}")
        logger.info("✅ Painéis restaurados como último em todos os canais")
    except Exception as e:
        logger.error(f"❌ Erro ao restaurar painéis últimos: {e}")
    gc.collect()
    logger.info("=" * 50)
    logger.info("✅ BOT ONLINE 100% COMPLETO - v8.0")
    logger.info("=" * 50)

# ────────────────────────────────────────────────────────────────────────────────
# EVENTO: on_message (MOVE PAINÉIS PRO FINAL SEMPRE)
# ────────────────────────────────────────────────────────────────────────────────
@bot.event
async def on_message(message: discord.Message):
    if message.author.id == 1100419913971150868:
        return

    if message.author.bot:
        return

    canal = message.channel

    # ═══════════════════════════════════════════════════════════════════════════
    # DETECÇÃO DE COMPROVANTE DE DOAÇÃO NO DM
    # ═══════════════════════════════════════════════════════════════════════════
    if isinstance(canal, discord.DMChannel):
        if message.attachments:
            anexo = message.attachments[0]
            if anexo.content_type and (anexo.content_type.startswith("image/") or anexo.content_type == "application/pdf"):
                canal_log = bot.get_channel(CANAL_LOG_DOACOES_ID)
                if canal_log:
                    embed = discord.Embed(
                        title="🧾 COMPROVANTE DE DOAÇÃO RECEBIDO",
                        description=f"O membro **{message.author.mention}** enviou um comprovante no DM.",
                        color=0x2ECC71,
                        timestamp=agora()
                    )
                    embed.add_field(name="👤 Usuário", value=f"{message.author.name} ({message.author.id})", inline=False)
                    embed.add_field(name="📎 Arquivo", value=f"[Clique para baixar]({anexo.url})", inline=False)
                    embed.set_image(url=anexo.url)
                    embed.set_footer(text="Verifique no extrato bancário e confirme a doação.")
                    
                    await canal_log.send(embed=embed)
                    await message.reply("✅ **Comprovante recebido!**\nA gerência foi notificada e vai verificar o pagamento. Muito obrigado pela doação! ❤️")
                else:
                    await message.reply("✅ **Comprovante recebido!**\nMas houve um erro interno ao notificar a gerência. Por favor, envie o print no canal de doações.")
                return # Para o bot não processar mais nada dessa mensagem

    if isinstance(canal, discord.TextChannel):
        # ═══════════════════════════════════════════════════════════════════════
        # PRIORIDADE 1: canal de meta (de um membro)
        # ═══════════════════════════════════════════════════════════════════════
        for uid, dados in list(metas_cache.items()):
            if dados["canal_id"] == canal.id:
                try:
                    await asyncio.sleep(2)
                    await fixar_painel_meta_no_final(int(uid))
                except Exception as e:
                    logger.error(f"Erro ao fixar painel de meta: {e}")
                break

        # ═══════════════════════════════════════════════════════════════════════
        # PRIORIDADE 2: qualquer outro painel registrado em paineis_ultimos
        # ═══════════════════════════════════════════════════════════════════════
        try:
            await verificar_e_mover_paineis(canal)
        except Exception as e:
            logger.error(f"❌ Erro ao mover painéis do canal {canal.name}: {e}")

    await on_message_lavagem(message)
    await on_message_bau_ocr(message)

    # Registra atividade (inatividade detector)
    try:
        if message.guild and message.guild.id == GUILD_ID:
            await _registrar_atividade(message.author.id, "mensagem")
    except Exception as e:
        logger.error(f"❌ Erro ao registrar atividade mensagem: {e}")

    await bot.process_commands(message)
# ────────────────────────────────────────────────────────────────────────────────
# FUNÇÃO: shutdown
# ────────────────────────────────────────────────────────────────────────────────
async def shutdown():
    logger.info("🔄 Iniciando shutdown gracioso...")
    global http_session
    if http_session:
        await http_session.close()
    pool = get_db()
    if pool:
        await pool.close()
    tasks = [t for t in asyncio.all_tasks() if t is not asyncio.current_task()]
    for task in tasks:
        task.cancel()
    await asyncio.gather(*tasks, return_exceptions=True)
    await bot.close()

